// src/runtime/safe-env.ts
var ALLOWED_KEYS = new Set([
  'PATH',
  'HOME',
  'USER',
  'USERNAME',
  'LANG',
  'LC_ALL',
  'LC_CTYPE',
  'TMP',
  'TEMP',
  'TMPDIR',
  'NODE_ENV',
  'NO_COLOR',
  'TERM',
  'HTTP_PROXY',
  'HTTPS_PROXY',
  'NO_PROXY',
  'http_proxy',
  'https_proxy',
  'no_proxy',
  'ALL_PROXY',
  'all_proxy',
]);
var BLOCKED_PATTERNS = [
  /_API_KEY$/i,
  /_AUTH_TOKEN$/i,
  /_SECRET$/i,
  /_PASSWORD$/i,
  /^JWT_SECRET$/i,
  /^GITHUB_TOKEN$/i,
  /^CODECX_/i,
  /^ANTHROPIC_/i,
  /^OPENAI_/i,
  /^GOOGLE_/i,
  /^GEMINI_/i,
  /^CLINE_/i,
  /^AWS_/i,
  /^AZURE_/i,
  /^GCP_/i,
  /^VAULT_/i,
];
function isBlocked(key) {
  if (ALLOWED_KEYS.has(key)) return false;
  return BLOCKED_PATTERNS.some((re) => re.test(key));
}
function getSafeSubprocessEnv(extra = {}) {
  const out = {};
  for (const key of ALLOWED_KEYS) {
    const val = process.env[key];
    if (val !== undefined && val !== '') out[key] = val;
  }
  for (const [key, value] of Object.entries(extra)) {
    if (!isBlocked(key) && value !== undefined && value !== '') out[key] = value;
  }
  return out;
}

// src/providers/gemini.ts
class GeminiProvider {
  config;
  name;
  constructor(config) {
    this.config = config;
    this.name = config.name === 'vertexai' ? 'vertexai' : 'google';
  }
  isAvailable() {
    const hasAuth =
      this.name === 'vertexai'
        ? !!(this.config.apiKey || this.config.authToken)
        : !!(this.config.apiKey || this.config.authToken || detectGeminiCLIToken());
    return !this.config.disabled && hasAuth;
  }
  cachedModels = null;
  lastFetch = 0;
  listModels() {
    const localModels = getModelsForProvider(this.name);
    if (this.name !== 'google') return localModels;
    if (!this.isAvailable()) return localModels;
    if (this.cachedModels && Date.now() - this.lastFetch < 5 * 60 * 1000) {
      return this.cachedModels;
    }
    this.refreshModelsInBackground(localModels);
    return this.cachedModels ?? localModels;
  }
  refreshModelsInBackground(localModels) {
    const apiKey = this.config.apiKey || this.config.authToken || detectGeminiCLIToken();
    if (!apiKey) return;
    const url = `${GEMINI_V1BETA_BASE}/models?key=${encodeURIComponent(apiKey)}`;
    withRetry(() =>
      fetch(url).then((r) => (r.ok ? r.json() : Promise.reject(new Error(r.statusText)))),
    )
      .then((body) => {
        const remote = [];
        for (const m of body.models ?? []) {
          const name = m.name;
          if (!name || !name.startsWith('models/')) continue;
          const id = name.replace(/^models\//, '');
          if (localModels.some((l) => l.id === id || l.apiModelId === id)) continue;
          const def2 = createGenericModel(id, 'google');
          def2.apiModelId = id;
          remote.push(def2);
        }
        this.cachedModels = [...localModels, ...remote];
        this.lastFetch = Date.now();
      })
      .catch(() => {
        if (!this.cachedModels) this.cachedModels = localModels;
      });
  }
  async *streamResponse(request) {
    const { GoogleGenAI: GoogleGenAI2 } = await Promise.resolve().then(
      () => (init_node(), exports_node),
    );
    const apiKey =
      this.config.apiKey ||
      this.config.authToken ||
      (this.name !== 'vertexai' ? detectGeminiCLIToken() : null);
    if (!apiKey) {
      yield {
        type: 'error',
        error:
          this.name === 'vertexai'
            ? 'Vertex AI requires an explicit API key (set GOOGLE_VERTEX_AI_API_KEY)'
            : 'No API key available',
      };
      return;
    }
    const clientOptions = { apiKey };
    if (this.config.baseUrl) {
      clientOptions.baseUrl = this.config.baseUrl;
    }
    const client = new GoogleGenAI2(clientOptions);
    const contents = request.messages
      .filter((m) => m.role !== 'system')
      .map((m) => ({
        role: m.role === 'assistant' ? 'model' : 'user',
        parts:
          typeof m.content === 'string'
            ? [{ text: m.content }]
            : m.content.map((b) => (b.type === 'text' ? { text: b.text ?? '' } : { text: '' })),
      }));
    const generationConfig = {
      systemInstruction: request.systemPrompt,
      maxOutputTokens: request.maxTokens ?? 65536,
      temperature: request.temperature,
    };
    const modelDef = resolveModel(request.model);
    const apiModel = modelDef?.apiModelId || request.model;
    const isGemini3 = /gemini-3/i.test(request.model) || /gemini-3/i.test(apiModel ?? '');
    if (request.reasoningLevel !== undefined && request.reasoningLevel !== '') {
      const level = String(request.reasoningLevel).trim();
      if (isGemini3) {
        const thinkingLevel = ['low', 'medium', 'high'].includes(level.toLowerCase())
          ? level.toUpperCase()
          : 'MEDIUM';
        generationConfig.thinkingConfig = { thinkingLevel };
      } else {
        const budget =
          level === '0' || level.toLowerCase() === 'off'
            ? 0
            : Math.max(0, parseInt(level, 10) || 8192);
        generationConfig.thinkingConfig = { thinkingBudget: budget };
      }
    }
    try {
      const response = await client.models.generateContentStream({
        model: apiModel,
        contents,
        config: generationConfig,
      });
      for await (const chunk of response) {
        const candidate = chunk.candidates?.[0];
        if (!candidate?.content?.parts) continue;
        for (const part of candidate.content.parts) {
          if (part.text) yield { type: 'content_delta', content: part.text };
        }
        if (candidate.finishReason) yield { type: 'complete', finishReason: 'end_turn' };
      }
    } catch (err) {
      yield { type: 'error', error: err.message ?? String(err) };
    }
  }
}

class GeminiCLIProvider {
  config;
  name;
  cliAvailable = null;
  constructor(config) {
    this.config = config;
    this.name = 'google';
  }
  isAvailable() {
    const hasAuth = this.config.authToken?.startsWith('cli:') || !!detectGeminiCLIToken();
    if (!hasAuth || this.config.disabled) return false;
    if (this.cliAvailable === null) {
      this.cliAvailable = Bun.which('gemini') !== null;
    }
    return this.cliAvailable;
  }
  listModels() {
    return getModelsForProvider(this.name);
  }
  async *streamResponse(request) {
    const modelDef = resolveModel(request.model);
    let cliModel = modelDef?.apiModelId || request.model;
    if (request.model === 'auto-gemini-3') cliModel = 'gemini-3';
    if (request.model === 'auto-gemini-2.5') cliModel = 'gemini-2.5';
    const prompt = request.messages
      .filter((m) => m.role === 'user')
      .map((m) => (typeof m.content === 'string' ? m.content : '')).join(`
`);
    const proc = Bun.spawn(['gemini', '--model', cliModel, '--prompt', prompt], {
      stdout: 'pipe',
      stderr: 'pipe',
      env: getSafeSubprocessEnv(),
    });
    const GEMINI_STREAM_TIMEOUT_MS = 300000;
    const killAndReap = () => {
      try {
        proc.kill();
      } catch {}
    };
    const timeoutId = setTimeout(killAndReap, GEMINI_STREAM_TIMEOUT_MS);
    const reader = proc.stdout.getReader();
    const decoder = new TextDecoder();
    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        const text = decoder.decode(value, { stream: true });
        if (text) yield { type: 'content_delta', content: text };
      }
      clearTimeout(timeoutId);
      yield { type: 'complete', finishReason: 'end_turn' };
    } catch (err) {
      killAndReap();
      yield { type: 'error', error: err.message ?? String(err) };
    } finally {
      clearTimeout(timeoutId);
      reader.releaseLock();
      killAndReap();
      try {
        await Promise.race([proc.exited, new Promise((r) => setTimeout(r, 2000))]);
      } catch {}
    }
  }
}

// src/providers/copilot.ts
import { readFileSync as readFileSync2, existsSync as existsSync2 } from 'fs';
import { join as join4 } from 'path';
import { homedir as homedir2 } from 'os';
init_logger();
var COPILOT_CHAT_URL = 'https://api.githubcopilot.com';
var COPILOT_HEADERS = {
  'Editor-Version': 'vscode/1.100.0',
  'Editor-Plugin-Version': 'copilot-chat/0.27.0',
  'Copilot-Integration-Id': 'vscode-chat',
  'User-Agent': 'Koryphaios/1.0',
};

class CopilotProvider extends OpenAIProvider {
  bearerToken = null;
  githubToken = null;
  constructor(config) {
    const ghToken = config.authToken ?? detectCopilotToken2();
    super(
      {
        ...config,
        apiKey: 'placeholder-will-be-fetched-async',
        authToken: ghToken ?? undefined,
        headers: { ...config.headers, ...COPILOT_HEADERS },
      },
      'copilot',
      COPILOT_CHAT_URL,
    );
    this.githubToken = ghToken;
  }
  listModels() {
    return CopilotModels;
  }
  isAvailable() {
    return !this.config.disabled && !!(this.config.authToken || detectCopilotToken2());
  }
  _copilotClient = null;
  get client() {
    if (!this._copilotClient) {
      this._copilotClient = new openai_default({
        apiKey: this.bearerToken || 'placeholder-awaiting-async-init',
        baseURL: COPILOT_CHAT_URL,
        defaultHeaders: { ...this.config.headers },
      });
    }
    return this._copilotClient;
  }
  async *streamResponse(request) {
    await this.ensureBearerToken();
    yield* super.streamResponse(request);
  }
  async ensureBearerToken() {
    if (this.bearerToken) return;
    if (!this.githubToken) {
      this.githubToken = detectCopilotToken2();
    }
    if (!this.githubToken) {
      throw new Error('GitHub Copilot token not found. Please authenticate.');
    }
    const bearer = await exchangeGitHubTokenForCopilotAsync(this.githubToken);
    if (bearer) {
      this.bearerToken = bearer;
      this._copilotClient = null;
    } else {
      throw new Error('Failed to exchange GitHub token for Copilot bearer token.');
    }
  }
}
function detectCopilotToken2() {
  const envToken = process.env.GITHUB_TOKEN ?? process.env.GITHUB_COPILOT_TOKEN;
  if (envToken) return envToken;
  const configDir = process.env.XDG_CONFIG_HOME ?? join4(homedir2(), '.config');
  const filePaths = [
    join4(configDir, 'github-copilot', 'hosts.json'),
    join4(configDir, 'github-copilot', 'apps.json'),
  ];
  for (const path2 of filePaths) {
    if (!existsSync2(path2)) continue;
    try {
      const data = JSON.parse(readFileSync2(path2, 'utf-8'));
      for (const key of Object.keys(data)) {
        if (key.includes('github.com')) {
          const oauthToken = data[key]?.oauth_token;
          if (typeof oauthToken === 'string' && oauthToken) return oauthToken;
        }
      }
    } catch {
      continue;
    }
  }
  return null;
}
async function exchangeGitHubTokenForCopilotAsync(githubToken) {
  try {
    const resp = await fetch('https://api.github.com/copilot_internal/v2/token', {
      method: 'GET',
      headers: {
        Authorization: `Token ${githubToken}`,
        'User-Agent': 'Koryphaios/1.0',
        Accept: 'application/json',
      },
    });
    if (!resp.ok) {
      const body = await resp.text();
      providerLog.error(
        { status: resp.status, body: body.slice(0, 200) },
        'Copilot token exchange failed',
      );
      return null;
    }
    const data = await resp.json();
    return data.token ?? null;
  } catch (err) {
    providerLog.error({ err }, 'Copilot token exchange error');
    return null;
  }
}
var DEFAULT_GITHUB_OAUTH_CLIENT_ID = 'Iv1.b507a08c87ecfe98';
async function startCopilotDeviceAuth() {
  const clientId = process.env.GITHUB_OAUTH_CLIENT_ID ?? DEFAULT_GITHUB_OAUTH_CLIENT_ID;
  const params = new URLSearchParams();
  params.append('client_id', clientId);
  params.append('scope', 'read:user');
  const response = await fetch('https://github.com/login/device/code', {
    method: 'POST',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: params.toString(),
  });
  if (!response.ok) {
    throw new Error(`Failed to start device auth: HTTP ${response.status}`);
  }
  const data = await response.json();
  return {
    deviceCode: data.device_code,
    userCode: data.user_code,
    verificationUri: data.verification_uri,
    verificationUriComplete: data.verification_uri_complete,
    expiresIn: data.expires_in,
    interval: data.interval ?? 5,
  };
}
async function pollCopilotDeviceAuth(deviceCode) {
  const clientId = process.env.GITHUB_OAUTH_CLIENT_ID ?? DEFAULT_GITHUB_OAUTH_CLIENT_ID;
  const params = new URLSearchParams();
  params.append('client_id', clientId);
  params.append('device_code', deviceCode);
  params.append('grant_type', 'urn:ietf:params:oauth:grant-type:device_code');
  const response = await fetch('https://github.com/login/oauth/access_token', {
    method: 'POST',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: params.toString(),
  });
  if (!response.ok) {
    throw new Error(`Failed to poll device auth: HTTP ${response.status}`);
  }
  const data = await response.json();
  return {
    accessToken: data.access_token,
    tokenType: data.token_type,
    scope: data.scope,
    error: data.error,
    errorDescription: data.error_description,
  };
}

