init_vault();
init_azure_kv();
init_gcp_kms();
init_logger();
init_providers();
function createKMSProviderFromEnv() {
  const provider = process.env.KORYPHAIOS_KMS_PROVIDER || 'local';
  switch (provider) {
    case 'local':
      serverLog.info('Using Local KMS provider (development only)');
      return new LocalKMSProvider({
        dataDir: process.env.KORYPHAIOS_DATA_DIR || '.koryphaios',
        passphrase: process.env.KORYPHAIOS_MASTER_KEY ?? process.env.KORYPHAIOS_KMS_PASSPHRASE,
        suppressWarning: true,
      });
    case 'aws-kms':
      serverLog.info('Using AWS KMS provider');
      return new AWSKMSProvider({
        region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
        keyId: process.env.KORYPHAIOS_KMS_KEY_ID,
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
        sessionToken: process.env.AWS_SESSION_TOKEN,
      });
    case 'vault':
      serverLog.info('Using HashiCorp Vault provider');
      return new VaultKMSProvider({
        address: process.env.VAULT_ADDR,
        keyName: process.env.KORYPHAIOS_KMS_KEY_NAME,
        authMethod: process.env.VAULT_AUTH_METHOD || 'token',
        authConfig: parseVaultAuthConfig(),
        namespace: process.env.VAULT_NAMESPACE,
      });
    case 'azure-kv':
      serverLog.info('Using Azure Key Vault provider');
      return new AzureKMSProvider({
        vaultName: process.env.KORYPHAIOS_KMS_VAULT_NAME,
        keyName: process.env.KORYPHAIOS_KMS_KEY_NAME,
        tenantId: process.env.AZURE_TENANT_ID,
        clientId: process.env.AZURE_CLIENT_ID,
        clientSecret: process.env.AZURE_CLIENT_SECRET,
      });
    case 'gcp-kms':
      serverLog.info('Using GCP KMS provider');
      return new GCPKMSProvider({
        projectId: process.env.GCP_PROJECT_ID,
        location: process.env.KORYPHAIOS_KMS_LOCATION,
        keyRing: process.env.KORYPHAIOS_KMS_KEY_RING,
        keyName: process.env.KORYPHAIOS_KMS_KEY_NAME,
        authMethod: process.env.GCP_SERVICE_ACCOUNT_KEY ? 'serviceAccount' : 'default',
        serviceAccountKey: process.env.GCP_SERVICE_ACCOUNT_KEY,
      });
    default:
      throw new Error(`Unknown KMS provider: ${provider}`);
  }
}
function parseVaultAuthConfig() {
  const method = process.env.VAULT_AUTH_METHOD || 'token';
  switch (method) {
    case 'token':
      return { token: process.env.VAULT_TOKEN };
    case 'approle':
      return {
        roleId: process.env.VAULT_ROLE_ID,
        secretId: process.env.VAULT_SECRET_ID,
      };
    case 'kubernetes':
      return {
        role: process.env.VAULT_K8S_ROLE,
      };
    case 'aws':
      return {
        role: process.env.VAULT_AWS_ROLE,
      };
    default:
      return { token: process.env.VAULT_TOKEN };
  }
}

// src/security.ts
var BLOCKED_PATTERNS2 = [
  /\brm\s+(-[a-zA-Z]*f[a-zA-Z]*\s+)?\/\s*$/,
  /\brm\s+(-[a-zA-Z]*f[a-zA-Z]*\s+)?\/\w/,
  /\bmkfs\b/,
  /\bdd\b/,
  /\b:(){ :|:& };:/,
  /\bchmod\s+(-R\s+)?777\s+\//,
  /\bchown\s+(-R\s+)?.*\s+\//,
  />\s*\/dev\/sd[a-z]/,
  /\bcurl\b.*\|\s*\bbash\b/,
  /\bwget\b.*\|\s*\bbash\b/,
  /\beval\b.*\$\(/,
  /\/etc\/passwd/,
  /\/etc\/shadow/,
  /\bsudo\b/,
  /\bsu\s+-?\s*$/,
  /\bshutdown\b/,
  /\breboot\b/,
  /\binit\s+[0-6]\b/,
  /\bsystemctl\s+(stop|disable|mask)\b/,
  /\bgcloud\s+auth\b/,
  /\bclaude\s+(login|auth)\b/,
  /\bcodex\s+(auth|login)\b/,
  /\bopenai\s+login\b/,
  /\bxdg-open\b/,
  /\bopen\b\s+https?:\/\//,
  /\$\(/,
  /`[^`]*`/,
  /\bpython[23]?\s+-c\b/,
  /\bperl\s+-e\b/,
  /\bruby\s+-e\b/,
  /\bnc\b.*-[elp]/,
  /\bncat\b/,
  /\bsocat\b/,
  /\bcrontab\b/,
  /\bat\b\s+/,
];
var BLOCKED_EXACT = new Set([
  'rm -rf /',
  'rm -rf /*',
  'rm -rf ~',
  'rm -rf ~/',
  ':(){ :|:& };:',
  'yes | rm -r /',
]);
function validateBashCommand(command) {
  const trimmed = command.trim();
  if (BLOCKED_EXACT.has(trimmed)) {
    return { safe: false, reason: `Blocked: destructive command "${trimmed}"` };
  }
  for (const pattern of BLOCKED_PATTERNS2) {
    if (pattern.test(trimmed)) {
      return {
        safe: false,
        reason: `Blocked: command matches dangerous pattern ${pattern.source}`,
      };
    }
  }
  const systemDirs = ['/boot', '/sys', '/proc/sys', '/usr/sbin', '/sbin'];
  for (const dir of systemDirs) {
    if (trimmed.includes(`> ${dir}`) || trimmed.includes(`>> ${dir}`)) {
      return { safe: false, reason: `Blocked: writing to system directory ${dir}` };
    }
  }
  return { safe: true };
}
