class PatchTool {
  name = 'patch';
  description = `Apply a multi-edit patch to a file. Each edit specifies old_str to find and new_str to replace it with. All edits are validated before any are applied (atomic). More efficient than multiple edit_file calls.`;
  inputSchema = {
    type: 'object',
    properties: {
      path: { type: 'string', description: 'Path to the file to patch.' },
      edits: {
        type: 'array',
        description: 'Array of edits to apply.',
        items: {
          type: 'object',
          properties: {
            old_str: { type: 'string', description: 'Exact string to find.' },
            new_str: { type: 'string', description: 'Replacement string.' },
          },
          required: ['old_str', 'new_str'],
        },
      },
    },
    required: ['path', 'edits'],
  };
  async run(ctx, call) {
    const { path: filePath, edits } = call.input;
    const absPath = filePath.startsWith('/') ? filePath : join9(ctx.workingDirectory, filePath);
    const allowedRoots = getAllowedRoots(ctx);
    const access = validatePathAccess(absPath, allowedRoots);
    if (!access.allowed) {
      return {
        callId: call.id,
        name: this.name,
        output: `Error: Access denied. ${access.reason}`,
        isError: true,
        durationMs: 0,
      };
    }
    if (!existsSync4(absPath)) {
      return {
        callId: call.id,
        name: this.name,
        output: `File not found: ${absPath}`,
        isError: true,
        durationMs: 0,
      };
    }
    if (!edits || edits.length === 0) {
      return {
        callId: call.id,
        name: this.name,
        output: 'No edits provided.',
        isError: true,
        durationMs: 0,
      };
    }
    try {
      let content = await Bun.file(absPath).text();
      for (let i = 0; i < edits.length; i++) {
        const occurrences = content.split(edits[i].old_str).length - 1;
        if (occurrences === 0) {
          return {
            callId: call.id,
            name: this.name,
            output: `Edit ${i + 1}: old_str not found in ${absPath}`,
            isError: true,
            durationMs: 0,
          };
        }
        if (occurrences > 1) {
          return {
            callId: call.id,
            name: this.name,
            output: `Edit ${i + 1}: old_str found ${occurrences} times. Must be unique.`,
            isError: true,
            durationMs: 0,
          };
        }
      }
      let totalAdded = 0;
      let totalDeleted = 0;
      for (const edit of edits) {
        totalAdded += edit.new_str.split(`
`).length;
        totalDeleted += edit.old_str.split(`
`).length;
        content = content.replace(edit.old_str, edit.new_str);
      }
      await Bun.write(absPath, content);
      if (ctx.recordChange) {
        ctx.recordChange({
          path: absPath,
          linesAdded: totalAdded,
          linesDeleted: totalDeleted,
          operation: 'edit',
        });
      }
      return {
        callId: call.id,
        name: this.name,
        output: `Applied ${edits.length} edit(s) to ${absPath}`,
        isError: false,
        durationMs: 0,
      };
    } catch (err) {
      return {
        callId: call.id,
        name: this.name,
        output: `Patch error: ${err instanceof Error ? err.message : String(err)}`,
        isError: true,
        durationMs: 0,
      };
    }
  }
}
function generateUnifiedDiff(fileName, oldLines, newLines) {
  const hunks = [];
  hunks.push(`--- a/${fileName}`);
  hunks.push(`+++ b/${fileName}`);
  let hasChanges = false;
  let i = 0,
    j = 0;
  while (i < oldLines.length || j < newLines.length) {
    if (i < oldLines.length && j < newLines.length && oldLines[i] === newLines[j]) {
      i++;
      j++;
      continue;
    }
    const contextStart = Math.max(0, i - 3);
    let oldEnd = i;
    let newEnd = j;
    while (oldEnd < oldLines.length || newEnd < newLines.length) {
      if (
        oldEnd < oldLines.length &&
        newEnd < newLines.length &&
        oldLines[oldEnd] === newLines[newEnd]
      ) {
        let matchCount = 0;
        while (
          oldEnd + matchCount < oldLines.length &&
          newEnd + matchCount < newLines.length &&
          oldLines[oldEnd + matchCount] === newLines[newEnd + matchCount]
        ) {
          matchCount++;
          if (matchCount >= 6) break;
        }
        if (matchCount >= 6) break;
        oldEnd += matchCount || 1;
        newEnd += matchCount || 1;
      } else if (
        oldEnd < oldLines.length &&
        (newEnd >= newLines.length || oldLines[oldEnd] !== newLines[newEnd])
      ) {
        oldEnd++;
      } else {
        newEnd++;
      }
    }
    const contextEnd = Math.min(
      Math.max(oldEnd, newEnd) + 3,
      Math.max(oldLines.length, newLines.length),
    );
    const oldContextEnd = Math.min(oldEnd + 3, oldLines.length);
    const newContextEnd = Math.min(newEnd + 3, newLines.length);
    hunks.push(
      `@@ -${contextStart + 1},${oldContextEnd - contextStart} +${contextStart + 1},${newContextEnd - contextStart} @@`,
    );
    for (let c = contextStart; c < i; c++) {
      hunks.push(` ${oldLines[c]}`);
    }
    for (let c = i; c < oldEnd; c++) {
      hunks.push(`-${oldLines[c]}`);
      hasChanges = true;
    }
    for (let c = j; c < newEnd; c++) {
      hunks.push(`+${newLines[c]}`);
      hasChanges = true;
    }
    for (let c = oldEnd; c < oldContextEnd; c++) {
      hunks.push(` ${oldLines[c]}`);
    }
    i = oldContextEnd;
    j = newContextEnd;
  }
  return hasChanges
    ? hunks.join(`
`)
    : null;
}
