var MAX_REDIRECTS = 5;
var DEFAULT_MAX_LENGTH = 1e4;
var USER_AGENT = 'Koryphaios/1.0 (AI Agent; +https://github.com/micahcooley/Koryphaios)';

class WebSearchTool {
  name = 'web_search';
  role = 'worker';
  description =
    'Search the web for current information. Returns snippets from search results. Use this liberally \u2014 agents perform better when they can verify information.';
  inputSchema = {
    type: 'object',
    properties: {
      query: { type: 'string', description: 'The search query.' },
      maxResults: { type: 'number', description: 'Max results to return (default: 5, max: 10).' },
    },
    required: ['query'],
  };
  async run(ctx, call) {
    const query = call.input.query;
    const maxResults = Math.min(call.input.maxResults || 5, 10);
    if (!query || typeof query !== 'string' || query.trim().length === 0) {
      return {
        callId: call.id,
        name: this.name,
        output: 'Error: query must be a non-empty string.',
        isError: true,
        durationMs: 0,
      };
    }
    try {
      const encoded = encodeURIComponent(query.trim());
      const searchUrl = `https://html.duckduckgo.com/html/?q=${encoded}`;
      const resp = await fetch(searchUrl, {
        headers: { 'User-Agent': USER_AGENT },
        signal: ctx.signal,
        redirect: 'follow',
      });
      if (!resp.ok) {
        return {
          callId: call.id,
          name: this.name,
          output: `Search failed: HTTP ${resp.status}`,
          isError: true,
          durationMs: 0,
        };
      }
      const html = await resp.text();
      const results = parseSearchResults(html, maxResults);
      if (results.length === 0) {
        return {
          callId: call.id,
          name: this.name,
          output: `No results found for: ${query}`,
          isError: false,
          durationMs: 0,
        };
      }
      const output = results.map(
        (r, i) => `[${i + 1}] ${r.title}
    ${r.url}
    ${r.snippet}`,
      ).join(`

`);
      return {
        callId: call.id,
        name: this.name,
        output: `Search results for "${query}":

${output}`,
        isError: false,
        durationMs: 0,
      };
    } catch (err) {
      return {
        callId: call.id,
        name: this.name,
        output: `Search error: ${err.message}`,
        isError: true,
        durationMs: 0,
      };
    }
  }
}

