class AskUserTool {
  name = 'ask_user';
  role = 'manager';
  description =
    "Ask the user a question and provide multiple options for them to choose from. Use this when you need user guidance, approval, or clarification on how to proceed. Always include an 'Other' option.";
  inputSchema = {
    type: 'object',
    properties: {
      question: { type: 'string', description: 'The question to ask the user' },
      options: {
        type: 'array',
        items: { type: 'string' },
        description:
          "List of options for the user to choose from (e.g. ['Apply changes', 'Discard changes', 'Other...'])",
      },
    },
    required: ['question', 'options'],
  };
  async run(ctx, call) {
    const { question, options } = call.input;
    if (!ctx.waitForUserInput) {
      return {
        callId: call.id,
        name: this.name,
        output: 'Error: User input system not available in this context.',
        isError: true,
        durationMs: 0,
      };
    }
    try {
      const selection = await ctx.waitForUserInput(question, options);
      return {
        callId: call.id,
        name: this.name,
        output: `User selected: ${selection}`,
        isError: false,
        durationMs: 0,
      };
    } catch (err) {
      return {
        callId: call.id,
        name: this.name,
        output: `Error waiting for user input: ${err.message}`,
        isError: true,
        durationMs: 0,
      };
    }
  }
}

class DelegateToWorkerTool {
  name = 'delegate_to_worker';
  role = 'manager';
  description =
    'Delegate a task to a specialist worker (sub-agent) only when you have explicitly decided that the task needs a dedicated coder and cannot be handled by you. Sub-agents (general, ui, backend, test, review) run only when you call this tool\u2014never for conversation, clarification, or small edits. Use only for substantial implementation, refactoring, or multi-file work. Provide a clear, self-contained task description. Optional: domain hint (ui | backend | general | test | review).';
  inputSchema = {
    type: 'object',
    properties: {
      task: { type: 'string', description: 'Clear task description for the worker' },
      domain: { type: 'string', description: 'Optional: ui | backend | general | test | review' },
    },
    required: ['task'],
  };
  async run(ctx, call) {
    const { task, domain } = call.input;
    if (!task || typeof task !== 'string' || !task.trim()) {
      return {
        callId: call.id,
        name: this.name,
        output: 'Error: task is required.',
        isError: true,
        durationMs: 0,
      };
    }
    if (!ctx.delegateToWorker) {
      return {
        callId: call.id,
        name: this.name,
        output: 'Error: Delegation not available in this context.',
        isError: true,
        durationMs: 0,
      };
    }
    try {
      const result = await ctx.delegateToWorker(task.trim(), domain);
      return { callId: call.id, name: this.name, output: result, isError: false, durationMs: 0 };
    } catch (err) {
      return {
        callId: call.id,
        name: this.name,
        output: `Delegation failed: ${err.message ?? String(err)}`,
        isError: true,
        durationMs: 0,
      };
    }
  }
}

class AskManagerTool {
  name = 'ask_manager';
  role = 'worker';
  description =
    'Ask the Manager for help, clarification, or professional advice when you are confused. You can also use this to REQUEST that the Manager asks the User a question if you believe user input is required for a project-level decision.';
  inputSchema = {
    type: 'object',
    properties: {
      question: {
        type: 'string',
        description: 'The specific question or problem you need help with',
      },
    },
    required: ['question'],
  };
  async run(ctx, call) {
    return {
      callId: call.id,
      name: this.name,
      output: JSON.stringify({
        type: 'INTERVENTION_REQUEST',
        question: call.input.question,
      }),
      isError: false,
      durationMs: 0,
    };
  }
}
