// src/kory/critic-util.ts
function parseCriticVerdict(content) {
  const lines = content
    .trim()
    .split(/\n/)
    .map((l) => l.trim())
    .filter(Boolean);
  const lastLine = lines[lines.length - 1] ?? '';
  const upper = lastLine.toUpperCase();
  if (upper.startsWith('PASS')) return true;
  if (upper.startsWith('FAIL')) return false;
  return content.toUpperCase().includes('PASS');
}
function formatMessagesForCritic(messages, maxLength = 12000) {
  const raw = messages
    .map((m) => {
      if (m.role === 'user')
        return `[USER]
${m.content}`;
      if (m.role === 'assistant')
        return `[ASSISTANT]
${m.content}`;
      if (m.role === 'tool')
        return `[TOOL RESULT]
${m.content}`;
      return '';
    })
    .filter(Boolean).join(`

---

`);
  if (raw.length <= maxLength) return raw;
  return (
    raw.slice(0, maxLength) +
    `

...[truncated]`
  );
}

