var SESSION_TTL_MS = 60 * 60 * 1000;

class SessionReplyStream {
  sessions = new Map();
  listeners = new Map();
  push(sessionId, segment) {
    let q = this.sessions.get(sessionId);
    if (!q) {
      q = { segments: [], createdAt: Date.now() };
      this.sessions.set(sessionId, q);
    }
    q.segments.push(segment);
    const list = this.listeners.get(sessionId);
    if (list) {
      for (const ctrl of list) {
        try {
          ctrl.enqueue(segment);
        } catch {
          list.splice(list.indexOf(ctrl), 1);
        }
      }
    }
    if (segment.done) {
      this.listeners.delete(sessionId);
      setTimeout(() => this.dropSession(sessionId), 5000);
    }
  }
  getStream(sessionId) {
    const self2 = this;
    return new ReadableStream({
      start(controller) {
        const q = self2.sessions.get(sessionId);
        if (q) {
          for (const seg of q.segments) {
            controller.enqueue(seg);
            if (seg.done) {
              controller.close();
              return;
            }
          }
        }
        let list = self2.listeners.get(sessionId);
        if (!list) {
          list = [];
          self2.listeners.set(sessionId, list);
        }
        list.push(controller);
      },
      cancel() {},
    });
  }
  getPending(sessionId) {
    const q = this.sessions.get(sessionId);
    return q ? [...q.segments] : [];
  }
  dropSession(sessionId) {
    this.sessions.delete(sessionId);
    this.listeners.delete(sessionId);
  }
  prune() {
    const now = Date.now();
    for (const [id, q] of this.sessions) {
      if (now - q.createdAt > SESSION_TTL_MS) {
        this.sessions.delete(id);
        this.listeners.delete(id);
      }
    }
  }
}
