init_logger();

class MessagingGateway {
  sessionToAdapter = new Map();
  reader = null;
  running = false;
  registerSession(sessionId, adapter) {
    this.sessionToAdapter.set(sessionId, adapter);
    messagingLog.debug(
      { sessionId, channelId: adapter.channelId },
      'Session registered for messaging',
    );
  }
  unregisterSession(sessionId) {
    this.sessionToAdapter.delete(sessionId);
  }
  start() {
    if (this.running) return;
    this.running = true;
    const stream = wsBroker.subscribe();
    this.reader = stream.getReader();
    this.pump();
    messagingLog.info('Messaging gateway started');
  }
  async pump() {
    const r = this.reader;
    if (!r) return;
    try {
      while (true) {
        const { done, value } = await r.read();
        if (done) break;
        const msg = value.payload;
        const sessionId = msg.sessionId;
        if (!sessionId) continue;
        const adapter = this.sessionToAdapter.get(sessionId);
        if (!adapter) continue;
        const segment = this.toReplySegment(sessionId, msg);
        if (!segment) continue;
        sessionReplyStream.push(sessionId, segment);
        adapter.sendReply(sessionId, segment).catch((err) => {
          messagingLog.warn(
            { err, sessionId, channelId: adapter.channelId },
            'Adapter sendReply failed',
          );
        });
        if (segment.done) {
          this.sessionToAdapter.delete(sessionId);
        }
      }
    } catch (err) {
      messagingLog.error({ err }, 'Messaging gateway pump error');
    } finally {
      this.running = false;
      this.reader = null;
    }
  }
  toReplySegment(sessionId, msg) {
    const pl = msg.payload;
    switch (msg.type) {
      case 'stream.delta':
        return {
          type: 'delta',
          sessionId,
          content: typeof pl.content === 'string' ? pl.content : undefined,
        };
      case 'agent.status': {
        const status = pl.status;
        const done = status === 'done';
        return {
          type: 'status',
          sessionId,
          status,
          done,
        };
      }
      case 'system.error':
        return {
          type: 'error',
          sessionId,
          error: typeof pl.error === 'string' ? pl.error : String(pl.error),
          done: true,
        };
      case 'kory.thought':
        return {
          type: 'status',
          sessionId,
          status: typeof pl.thought === 'string' ? pl.thought : '',
        };
      default:
        return null;
    }
  }
  stop() {
    this.running = false;
    if (this.reader) {
      this.reader.cancel().catch((err) => {
        messagingLog.warn({ err }, 'Failed to cancel messaging gateway reader');
      });
      this.reader = null;
    }
    this.sessionToAdapter.clear();
    messagingLog.info('Messaging gateway stopped');
  }
}
