// src/providers/google-auth.ts
var { spawn } = globalThis.Bun;

class GoogleAuthManager {
  async startGeminiCLIAuth() {
    return new Promise((resolve6) => {
      const proc = spawn(
        ['gcloud', 'auth', 'application-default', 'login', '--no-launch-browser'],
        {
          stdout: 'pipe',
          stderr: 'pipe',
        },
      );
      let output = '';
      let resolved = false;
      const timeout = setTimeout(() => {
        if (!resolved) {
          proc.kill();
          resolve6({ success: false, message: 'Authentication timed out after 5 minutes' });
        }
      }, 300000);
      const decoder = new TextDecoder();
      const readStream = async (reader) => {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          const text = decoder.decode(value);
          output += text;
          const urlMatch = text.match(/(https:\/\/accounts\.google\.com\/o\/oauth2\/auth\S+)/);
          if (urlMatch && !resolved) {
            resolved = true;
            resolve6({
              success: true,
              message: 'Please open the URL to authorize Google Cloud ADC',
              url: urlMatch[1],
            });
          }
        }
      };
      readStream(proc.stdout.getReader());
      readStream(proc.stderr.getReader());
      proc.exited
        .then((code) => {
          clearTimeout(timeout);
          if (resolved) return;
          resolved = true;
          if (code === 0) {
            resolve6({ success: true, message: 'Google Cloud ADC authenticated successfully' });
          } else {
            resolve6({
              success: false,
              message: `gcloud CLI failed. Ensure Google Cloud SDK is installed. Output: ${output.slice(0, 200)}`,
            });
          }
        })
        .catch((err) => {
          clearTimeout(timeout);
          if (resolved) return;
          resolved = true;
          resolve6({ success: false, message: `gcloud process error: ${String(err)}` });
        });
    });
  }
}
var googleAuth = new GoogleAuthManager();

