init_sqlite();
class SessionStore {
  create(titleOrUserId, titleOrTitle, parentId) {
    const argc = arguments.length;
    const userId = argc >= 1 ? (titleOrUserId ?? null) : null;
    const title =
      argc >= 2
        ? (titleOrTitle ?? SESSION.DEFAULT_TITLE)
        : (titleOrUserId ?? SESSION.DEFAULT_TITLE);
    const parent = argc >= 3 ? parentId : argc === 2 ? undefined : titleOrTitle;
    const id = nanoid(ID.SESSION_ID_LENGTH);
    const now = Date.now();
    const db3 = getDb();
    db3.run(
      'INSERT INTO sessions (id, user_id, title, parent_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?)',
      [id, userId, title ?? SESSION.DEFAULT_TITLE, parent || null, now, now],
    );
    return {
      id,
      title: title ?? SESSION.DEFAULT_TITLE,
      parentSessionId: parent || undefined,
      messageCount: 0,
      totalTokensIn: 0,
      totalTokensOut: 0,
      totalCost: 0,
      createdAt: now,
      updatedAt: now,
    };
  }
  get(id) {
    const row = getDb().query('SELECT * FROM sessions WHERE id = ?').get(id);
    if (!row) return;
    return this.rowToSession(row);
  }
  list() {
    const rows = getDb().query('SELECT * FROM sessions ORDER BY updated_at DESC').all();
    return rows.map((row) => this.rowToSession(row));
  }
  listForUser(_userId) {
    return this.list();
  }
  getForUser(id, _userId) {
    return this.get(id);
  }
  rowToSession(row) {
    return {
      id: row.id,
      title: row.title,
      parentSessionId: row.parent_id,
      messageCount: row.message_count ?? 0,
      totalTokensIn: row.tokens_in ?? 0,
      totalTokensOut: row.tokens_out ?? 0,
      totalCost: row.total_cost ?? 0,
      version: row.version ?? 1,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }
  update(id, updates, expectedVersion) {
    const mapping = {
      title: 'title',
      messageCount: 'message_count',
      totalTokensIn: 'tokens_in',
      totalTokensOut: 'tokens_out',
      totalCost: 'total_cost',
      updatedAt: 'updated_at',
    };
    const fields = Object.keys(updates).filter(
      (k) => k !== 'id' && k !== 'version' && k in mapping,
    );
    if (fields.length === 0 && expectedVersion === undefined) return this.get(id);
    const db3 = getDb();
    const now = Date.now();
    if (expectedVersion !== undefined) {
      const sets = fields.map((f) => `${mapping[f]} = ?`).join(', ');
      const values = fields.map((f) => updates[f]);
      values.push(now);
      values.push(expectedVersion + 1);
      values.push(id);
      values.push(expectedVersion);
      const result = db3.run(
        `UPDATE sessions SET ${sets ? sets + ', ' : ''}updated_at = ?, version = ? WHERE id = ? AND version = ?`,
        values,
      );
      if (result.changes === 0) {
        throw new Error(
          `Concurrent modification detected: session ${id} was modified by another process`,
        );
      }
    } else {
      const sets = fields.map((f) => `${mapping[f]} = ?`).join(', ');
      const values = fields.map((f) => updates[f]);
      values.push(now);
      values.push(id);
      db3.run(`UPDATE sessions SET ${sets}, updated_at = ? WHERE id = ?`, values);
    }
    return this.get(id);
  }
  delete(id) {
    getDb().run('DELETE FROM sessions WHERE id = ?', [id]);
  }
  deleteForUser(id, _userId) {
    this.delete(id);
  }
  clear() {
    getDb().run('DELETE FROM sessions');
  }
}

