// src/server/websocket-handler.ts
init_logger();
async function handleWSOpen(ws, deps) {
  try {
    const { wsManager: wsManager2, providers: providers2 } = deps;
    wsManager2.add(ws);
    serverLog.info(
      { clientId: ws.data.id, clients: wsManager2.clientCount },
      'WS client connected',
    );
    try {
      const initialStatus = providers2.getStatus();
      ws.send(
        JSON.stringify({
          type: 'provider.status',
          payload: { providers: initialStatus },
          timestamp: Date.now(),
        }),
      );
    } catch (err) {
      serverLog.error(
        { err, event: 'ws.open.init_status', clientId: ws?.data?.id },
        'WS init status error',
      );
    }
  } catch (err) {
    serverLog.error({ err, event: 'ws.open', clientId: ws?.data?.id }, 'WS open error');
  }
}
async function handleWSMessage(ws, message, deps) {
  try {
    const { wsManager: wsManager2, sessions, kory } = deps;
    const msg = JSON.parse(String(message));
    const userId = ws.data.userId ?? 'local';
    const assertSessionOwnership = (sessionId) => {
      if (!sessionId || !validateSessionId(sessionId)) return false;
      const session = sessions.getForUser(sessionId, userId);
      return !!session;
    };
    switch (msg.type) {
      case 'subscribe_session':
        const sessionId = msg.sessionId;
        if (sessionId && validateSessionId(sessionId) && sessions.getForUser(sessionId, userId)) {
          wsManager2.subscribeClientToSession(ws.data.id, sessionId);
          serverLog.debug({ clientId: ws.data.id, sessionId }, 'Client subscribed to session');
        }
        break;
      case 'user_input':
        if (assertSessionOwnership(msg.sessionId)) {
          kory.handleUserInput(msg.sessionId, msg.selection, msg.text);
        } else {
          serverLog.warn({ sessionId: msg.sessionId, userId }, 'Unauthorized user_input attempt');
        }
        break;
      case 'session.accept_changes':
        if (assertSessionOwnership(msg.sessionId)) {
          kory.handleSessionResponse(msg.sessionId, true);
        } else {
          serverLog.warn(
            { sessionId: msg.sessionId, userId },
            'Unauthorized session.accept_changes attempt',
          );
        }
        break;
      case 'session.reject_changes':
        if (assertSessionOwnership(msg.sessionId)) {
          kory.handleSessionResponse(msg.sessionId, false);
        } else {
          serverLog.warn(
            { sessionId: msg.sessionId, userId },
            'Unauthorized session.reject_changes attempt',
          );
        }
        break;
      case 'toggle_yolo':
        kory.setYoloMode(!!msg.enabled);
        serverLog.info({ enabled: msg.enabled }, 'YOLO mode toggled via WebSocket');
        break;
      default:
        serverLog.warn({ type: msg.type }, 'Unknown WebSocket message type');
    }
  } catch (err) {
    serverLog.error(
      {
        err,
        event: 'ws.message',
        clientId: ws?.data?.id,
        raw: String(message).slice(0, 500),
      },
      'WS message error',
    );
  }
}
function handleWSClose(ws, wsManager2) {
  wsManager2.remove(ws);
  serverLog.info({ clients: wsManager2.clientCount }, 'WS client disconnected');
}
function createWebSocketHandlers(deps) {
  return {
    open: (ws) => handleWSOpen(ws, deps),
    message: (ws, message) => handleWSMessage(ws, message, deps),
    close: (ws) => handleWSClose(ws, deps.wsManager),
  };
}

