async function handleV1Routes(req, path2, method) {
  const requestId = generateRequestId();
  serverLog.debug({ requestId, path: path2, method }, 'V1 route handling');
  const startTime = Date.now();
  try {
    const handlers = [handleCredentials, handleBilling];
    for (const handler of handlers) {
      const result = await handler(req, path2, method, requestId);
      if (result !== null) {
        const duration3 = (Date.now() - startTime) / 1000;
        metrics.observeHistogram(
          'http_request_duration_seconds',
          { method, route: path2 },
          duration3,
        );
        metrics.incCounter('http_requests_total', {
          method,
          route: path2,
          status: String(result.status),
        });
        const headers = new Headers(result.headers);
        headers.set('X-Request-Id', requestId);
        return new Response(result.body, {
          status: result.status,
          headers,
        });
      }
    }
    return null;
  } catch (error48) {
    serverLog.error(
      { error: error48, requestId, path: path2, method },
      'Unhandled error in v1 routes',
    );
    const duration3 = (Date.now() - startTime) / 1000;
    metrics.observeHistogram('http_request_duration_seconds', { method, route: path2 }, duration3);
    metrics.incCounter('http_requests_total', { method, route: path2, status: '500' });
    return json2({ error: 'Internal server error', requestId }, 500, { 'X-Request-Id': requestId });
  }
}

